import StationOsmTags from "../assets/station-osm-tags.json";
import { OsmTagged } from "./types";

// The OSM name translations and operators of the stations, generated by scripts/generate-osm-data.js
// (clients don't query the Overpass API)
const STATION_OSM_DATA = new Map<string, OsmTagged>(
  Object.entries(StationOsmTags as Record<string, Record<string, string>>).map(([name, tags]) => [
    name,
    { tags: { name, ...tags } } as OsmTagged,
  ]),
);

/**
 * Get the OSM data (name translations, operator) of a station.
 * @param name - The name of the station.
 * @returns The station's OSM tags, or null if there are none.
 */
export function getStationOsmData(name: string): OsmTagged | null {
  return STATION_OSM_DATA.get(name) ?? null;
}

export function getOsmNodeName(stop: OsmTagged, lng: string): string {
  if (stop.tags[`name:${lng}`] && stop.tags[`name:${lng}`] !== stop.tags.name) {
    // If the name in the current language is different from the default name, return it
    return stop.tags[`name:${lng}`];
  }

  return stop.tags.name;
}
